export function createBetaPlanning(api){
 const panel=document.createElement('section');panel.id='betaPlanner';panel.hidden=true;panel.innerHTML=`<label>Your height <output id="plannerHeightValue"></output><input id="plannerHeight" type="range" min="140" max="205" step="1"></label><div class="planner-row"><button id="planRoute" class="dark">Suggest & climb ▶</button><button id="cancelPlan" hidden>Cancel</button></div><p id="plannerStatus" role="status">Both hands on the finish. Your way up.</p><progress id="plannerProgress" hidden></progress><button id="tryDynamic" hidden>Try a dynamic move ↗</button><p id="dynamicNote" class="planner-note" hidden>A small assisted jump, with a checked catch. Success is not guaranteed.</p>`;document.body.append(panel);panel.prepend(document.querySelector('.route-chooser'));
 const $=id=>panel.querySelector('#'+id);let generation=0,worker=null,busy=false,variant=0,stamp='',last=0,lastPose='',lastHeight=0,lastRoute='';
 function status(text){$('plannerStatus').textContent=text;}
 function cancel(message='Suggestion cancelled.'){generation++;worker?.terminate();worker=null;busy=false;$('plannerProgress').hidden=true;$('cancelPlan').hidden=true;$('planRoute').disabled=false;if(message)status(message);}
 async function plan(dynamic=false){cancel(null);const job=++generation;busy=true;api.stop();variant=0;$('tryDynamic').hidden=true;$('dynamicNote').hidden=true;stamp=api.fingerprint();$('planRoute').disabled=true;$('cancelPlan').hidden=false;$('plannerProgress').hidden=false;status('Reading the route’s grips…');
 try{const data=await api.prepare(dynamic);if(job!==generation)return;if(api.fingerprint()!==stamp){cancel('Route or pose changed. Press Suggest again.');return;}status('Finding hand and foot placements…');
 let checked,best=null;
 for(const allowDynamic of (dynamic?[true]:[false,true])){data.blocked=[];data.blockedEdges=[];if(allowDynamic)status("Checking whether a dynamic reach is needed…");
 for(let attempt=0;attempt<12;attempt++){
 const result=await new Promise((resolve,reject)=>{const reuseFit=!!worker;worker??=new Worker(new URL('./beta-planner-worker.js?v=fast-fit-1',import.meta.url),{type:'module'});worker.onerror=()=>reject(Error('The planner could not start. Your current moves are unchanged.'));worker.onmessage=({data})=>{if(job!==generation)return;if(data.error)reject(Error(data.error));else if(data.result)resolve(data.result);else if(data.stage)status(data.stage);else if(data.progress)status('Planning to the finish · '+data.progress+' steps');};worker.postMessage({...data,variant,allowDynamic,reuseFit});});if(job!==generation)return;
 checked=await api.validate(result,data,n=>{if(job!==generation)throw Error('Cancelled');status('Checking pose '+n+'…');});if(job!==generation)return;
 if(!best||checked.frames.length>best.frames.length||checked.complete)best=checked;
 if(checked.complete||(!checked.blocked&&!checked.blockedEdge))break;
 if(checked.blocked)data.blocked.push(checked.blocked);if(checked.blockedEdge)data.blockedEdges.push(checked.blockedEdge);status('Trying another way around a difficult position…');
 }if(best?.complete)break;}checked=best;if(api.fingerprint()!==stamp){cancel('Route or pose changed. Press Suggest again.');return;}

 worker?.terminate();worker=null;busy=false;$('plannerProgress').hidden=true;$('cancelPlan').hidden=true;$('planRoute').disabled=false;api.install(checked);status(checked.complete?'Both hands finish · '+Math.max(0,checked.frames.length-1)+' moves'+(checked.frames.some(f=>f.motion==='dyno')?' · includes a dynamic move.':'.'):dynamic?(checked.frames.some(f=>f.motion==='dyno')?'Dynamic move added. The route is not finished yet.':'No suitable jump found. You can edit the last move.'):checked.frames.length?'Partial climb · '+Math.max(0,checked.frames.length-1)+' moves'+(checked.frames.some(f=>f.motion==='dyno')?' · includes a dynamic move. ':'. ')+'The planner could not find a checked finish, even with dynamic catches.':(checked.reason||'Could not fit a starting stance for this height. Try another route.'));$('tryDynamic').hidden=checked.complete||checked.frames.length<1||(dynamic&&!checked.frames.slice(data.prefix?.length||0).some(f=>f.motion==='dyno'));$('dynamicNote').hidden=$('tryDynamic').hidden;if(checked.frames.length>1)api.play();
 }catch(error){if(job!==generation)return;cancel(null);status(error.message||'Could not suggest a route. Try adjusting the starting pose.');}}
 $('planRoute').onclick=()=>plan();$('tryDynamic').onclick=()=>plan(true);$('cancelPlan').onclick=()=>cancel();
 $('plannerHeight').oninput=e=>{cancel(null);api.height(+e.target.value);$('plannerHeightValue').textContent=e.target.value+' cm';status('Height changed. Suggest again to find a beta for this reach.');$('tryDynamic').hidden=true;$('dynamicNote').hidden=true;};
 return{update(){const now=performance.now();if(now-last<200)return;last=now;const s=api.state();panel.hidden=s.mode!=='beta'||document.body.classList.contains('beta-fine');if(s.mode!=='beta'){if(busy)cancel(null);return;}if(busy&&api.fingerprint()!==stamp)cancel('Route changed. Suggest again.');if(lastRoute!==s.route){lastRoute=s.route;status('Both hands on the finish. Your way up.');$('tryDynamic').hidden=true;$('dynamicNote').hidden=true;}if(lastHeight!==s.height){lastHeight=s.height;$('plannerHeight').value=s.height;$('plannerHeightValue').textContent=s.height+' cm';}}};
}
